const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const canberra = ee.Geometry.Point(149.1287, -35.2820); // Coordinates for Canberra, Australia
  const startDate = '2020-01-14';
  const endDate = '2020-01-22';
  const targetRainfallInches = 8;
  const targetRainfallMM = targetRainfallInches * 25.4; // Convert inches to millimeters

  // 2. Data Acquisition
  let chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, ee.Date(endDate).advance(1, 'day')) // Filter exclusive end date
    .filterBounds(canberra);

  // Check if the collection is empty
  const collectionSize = await chirps.size().getInfo();
  if (collectionSize === 0) {
    console.log(`No CHIRPS data found for the period ${startDate} to ${endDate}.`);
    console.log('C1');
    return;
  }

  console.log(`Number of images found: ${collectionSize}`);

  // Sum precipitation over the period
  const totalPrecipitationImage = chirps.sum();

  // 3. Processing & 4. Calculation
  // Reduce the summed image to get the total precipitation in mm for the point.
  // CHIRPS resolution is ~5.5km, so a scale of 5000m is appropriate.
  const precipitationStats = await totalPrecipitationImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: canberra,
    scale: 5000, // CHIRPS resolution is 0.05 degrees (~5.5km)
    maxPixels: 1e9,
    crs: 'EPSG:4326' // Use WGS84 as it's a global product
  }).getInfo();

  let totalRainfallMM = precipitationStats ? precipitationStats['precipitation'] : null;

  // 5. Validation & Final Answer
  if (totalRainfallMM === null || isNaN(totalRainfallMM)) {
    console.log('Calculation failed: Could not retrieve precipitation value.');
    console.log('C3');
    return;
  }

  // Convert total rainfall from mm to inches
  const totalRainfallInches = totalRainfallMM / 25.4;

  console.log(`Total rainfall (mm): ${totalRainfallMM.toFixed(2)}`);
  console.log(`Total rainfall (inches): ${totalRainfallInches.toFixed(2)}`);
  console.log(`Target rainfall (inches): ${targetRainfallInches.toFixed(2)}`);

  if (totalRainfallInches > targetRainfallInches) {
    console.log('A'); // Yes
  } else {
    console.log('B'); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
